def split_row(line: str):
    """Split one CSV line into fields. Fields may be double-quoted; inside a
    quoted field a comma is literal and a doubled quote is a literal quote."""
    fields = []
    field = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Escaped quote "" -> literal quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    # closing quote
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == '"':
                # start quoted field
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        i += 1
    # append last field
    fields.append(''.join(field))
    return fields
